// 1. Collect all open issues labeled bug (paginate until empty).
const issues: any[] = [];
for (let page = 1; page < 100; page++) {
  const r = await tools.list_issues({ repo: "acme/api", state: "open", label: "bug", page });
  const arr = toArr(r);
  if (arr.length === 0) break;
  issues.push(...arr);
  if (arr.length < 50) break;
}

// 2. For each, check assignee and count comments.
const results: any[] = [];
for (const it of issues) {
  const num = it.number ?? it.iid;
  const full = await tools.get_issue({ repo: "acme/api", number: num });
  const assignees = full.assignees ?? (full.assignee ? [full.assignee] : []);
  const unassigned = !full.assignee && (!Array.isArray(full.assignees) || full.assignees.length === 0);

  // count comments across pages
  let count = 0;
  for (let p = 1; p < 100; p++) {
    const c = toArr(await tools.list_comments({ repo: "acme/api", number: num, page: p }));
    count += c.length;
    if (c.length < 50) break;
  }
  results.push({
    number: num,
    state: full.state,
    labels: (full.labels ?? []).map((l: any) => (typeof l === "string" ? l : l.name)),
    assignee: full.assignee ?? null,
    assignees: full.assignees ?? null,
    unassigned,
    comments: count,
    reported_comments: full.comments ?? full.comments_count ?? null,
  });
}

const matches = results.filter(r => r.unassigned && r.comments > 5);
return {
  totalOpenBugIssues: issues.length,
  matchCount: matches.length,
  matches: matches.map(m => m.number),
  sample: results.slice(0, 3),
};
