  matches: matchNums,
  newVsPreviousSearch: matchNums.filter(n => !prevMatches.includes(n)),
  missingVsPreviousSearch: prevMatches.filter(n => !matchNums.includes(n)),
  errors: details.filter((d: any) => d.error).map((d: any) => d.number),
};
