  try {
    const full: any = await tools.get_issue({ repo: "acme/api", number: num });
    const labels = (full.labels ?? []).map((l: any) => (typeof l === "string" ? l : l.name));
    const hasAssignee = !!full.assignee || (Array.isArray(full.assignees) && full.assignees.length > 0);
    let count = 0;
    for (let p = 1; p < 20; p++) {
      const c = toArr(await tools.list_comments({ repo: "acme/api", number: num, page: p }));
      count += c.length;
      if (c.length < 50) break;
    }
